package com.Atom2Universe.app.games.caves.node

import android.graphics.Bitmap
import java.io.ByteArrayInputStream
import java.io.DataInputStream
import java.util.Base64
import java.util.zip.InflaterInputStream

/** Lossless code defaults for the 91 approved hand-edited tiles.
 * The remaining pack textures retain their existing drawing recipes.
 * These immutable pixel runs are independent of editable PNG files: changing a pack does not
 * change the fallback. Each record contains width/height, then unsigned-short run + ARGB int.
 */
internal object SelectedTextureDefaults {
    fun texture(key: String, size: Int): Bitmap {
        require(size > 0)
        val encoded = requireNotNull(data[key]) { "Unknown selected texture: $key" }
        val source = DataInputStream(InflaterInputStream(ByteArrayInputStream(Base64.getDecoder().decode(encoded)))).use { input ->
            val width = input.readUnsignedShort(); val height = input.readUnsignedShort()
            require(width in 1..96 && height in 1..96)
            val pixels = IntArray(width * height)
            var at = 0
            while (at < pixels.size) {
                val count = input.readUnsignedShort(); val color = input.readInt()
                require(count > 0 && at + count <= pixels.size)
                pixels.fill(color, at, at + count)
                at += count
            }
            Bitmap.createBitmap(pixels, width, height, Bitmap.Config.ARGB_8888)
        }
        if (source.width == size && source.height == size) return source
        return Bitmap.createScaledBitmap(source, size, size, false).also { source.recycle() }
    }

